// Multi-page HTML -> PDF renderer via Playwright (LinkedIn carousel / document post).
// The HTML stacks N `.page` sections; print CSS (`@page` + `break-after:page`) maps
// each section to one PDF page. Honors CSS page size via preferCSSPageSize.
// Lives in _pipeline/ to reuse the shared Playwright install.
// Usage: node _pipeline/render-pdf.mjs <html-path> <out-pdf> [width-css] [height-css]
//   ex.: node _pipeline/render-pdf.mjs ../../Éditorial/assets/carousel-x.html /tmp/carousel-x.pdf 1080px 1350px
//
// Version: 1.0
// Changelog:
// - 2026-06-22 - v1.0 - Initial. Carousel/document-post delivery (PDF) from a multi-`.page` HTML.
import { chromium } from 'playwright';
import { pathToFileURL } from 'node:url';
import { resolve } from 'node:path';

const [htmlArg, outArg, wArg = '1080px', hArg = '1350px'] = process.argv.slice(2);
if (!htmlArg || !outArg) {
  console.error('usage: node render-pdf.mjs <html-path> <out-pdf> [width-css] [height-css]');
  process.exit(1);
}
const htmlPath = resolve(htmlArg);
const outPath = resolve(outArg);

const browser = await chromium.launch();
const page = await browser.newPage();
await page.goto(pathToFileURL(htmlPath).href, { waitUntil: 'networkidle' });
await page.evaluate(() => document.fonts.ready);
await page.pdf({
  path: outPath,
  width: wArg,
  height: hArg,
  printBackground: true,
  preferCSSPageSize: true,
  margin: { top: 0, right: 0, bottom: 0, left: 0 },
});
await browser.close();
console.log(`rendered ${outPath} (${wArg} x ${hArg} per page)`);

